//go:build amd64

package floats

// The AVX2+FMA kernel of CMulZipRev (cmulziprev.go), generated by go-asmgen
// (cmulziprev_amd64_gen.go) into cmulziprev_amd64.s: four complex numbers per step, for
// a CPU with the AVX2+FMA of the other kernels (hasAVX2FMA); the portable loop
// otherwise. The Go code finishes the last numbers. go:noescape.
//
//go:noescape
func cmulZipRevAVX2(dst, x, y, w []float64)

func cmulZipRev(dst, x, y, w []float64) {
	from := 0
	if hasAVX2FMA {
		cmulZipRevAVX2(dst, x, y, w)
		from = (len(dst) / 2) &^ 3
	}
	zipRevTail(dst, x, y, w, from)
}
